/* eslint-disable no-prototype-builtins */

'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var Obj = require( './../lib' );


// MAIN //

bench( format( '%s::constructor', pkg ), function benchmark( b ) {
	var values;
	var o;
	var i;

	values = [
		null,
		void 0,
		5,
		'5',
		{},
		[]
	];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		o = new Obj( values[ i%values.length ] );
		if ( typeof o !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( typeof o !== 'object' ) {
		b.fail( 'should return an object' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::prototype.hasOwnProperty', pkg ), function benchmark( b ) {
	var o;
	var v;
	var i;

	o = {
		'a': 1,
		'b': 2,
		'c': 3
	};

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = o.hasOwnProperty( 'a' );
		if ( typeof v !== 'boolean' ) {
			b.fail( 'should return a boolean' );
		}
	}
	b.toc();
	if ( typeof v !== 'boolean' ) {
		b.fail( 'should return a boolean' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

